import {extractAndReview,reviewExisting} from './extraction-review.js';
import {createDuplicateUI} from './duplicates-ui.js';
import {openInboxMatch} from './matching.js';
import {openInboxCase} from './case-ui.js';
import {connectInbox} from './workflow-bridge.js';
import {sourceStamp,linkComparison,linkCase,effectiveFields} from './workflow-engine.js';
import {parseExtractedText} from './extraction.js';
import {money,issuesFor,processDocs,approve,csv,parseInvoice} from './engine.js';
import {samples,newDocs,sourceText} from './samples.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='accounting-demo-v1';let docs=newDocs(),events=[],filter='all',selected=null,busy=false;
try{const old=JSON.parse(localStorage.getItem(key));if(old?.version===1&&Array.isArray(old.docs)&&old.docs.every(d=>d.fields&&d.id&&typeof d.source==='string')){docs=old.docs;events=old.events||[];}}catch{}
connectInbox({get:id=>docs.find(d=>d.id===id),match:(context,invoice,po,result)=>{docs=docs.map(d=>d.id===context.id?linkComparison(d,context,invoice,po,result):d);recheck();log(`Compared ${invoice.number} with ${po.number}: ${result.hasDiscrepancy?'discrepancy on hold':'matched'}.`);render();},case:(context,c)=>{docs=docs.map(d=>d.id===context.id?linkCase(d,context,c):d);recheck();persist();render();}});
const labels={queued:'Queued',ready:'Ready to approve',review:'Needs review',approved:'Approved',rejected:'Rejected'};
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
function persist(){try{localStorage.setItem(key,JSON.stringify({version:1,docs,events}));}catch{toast('Browser storage unavailable. Changes will last for this session only.');}}
function log(message){events.unshift({message,time:new Date().toISOString()});persist();}
function recheck(){docs=docs.map(d=>['ready','review','approved'].includes(d.status)?{...d,status:issuesFor(d,docs).length?'review':d.status==='approved'?'approved':'ready'}:d);}
const duplicatesUI=createDuplicateUI({getDocs:()=>docs,update:next=>{docs=next;recheck();persist();render();},log,onImport:importQueueFiles});
async function importQueueFiles(files){if(busy){toast('Finish the current batch first.');return;}busy=true;try{for(const file of files.slice(0,20)){try{if(file.size>15*1024*1024)throw Error('Files must be under 15 MB.');let fields,source,invoiceDocument=null,documentType='invoice';if(/\.txt$/i.test(file.name)){source=await file.text();fields=parseInvoice(source);}else{let d;if(/\.json$/i.test(file.name)){d=JSON.parse(await file.text());if(d?.type==='credit_note')throw Error('Credit notes are unsupported; keep them separate from payable invoices.');if(!d||!['invoice','receipt'].includes(d.type))throw Error('JSON must describe an invoice or receipt.');}else d=await extractAndReview(file,'invoice',toast);if(!d)continue;delete d.supplierReview;invoiceDocument=structuredClone(d);documentType=d.type||'invoice';fields={vendor:d.vendor||'',number:d.number||'',date:d.date||'',due:d.due||'',subtotal:d.subtotal??(Array.isArray(d.lines)?d.lines.reduce((s,l)=>s+Number(l.quantity)*Number(l.unitPrice),0):null),tax:d.tax??null,total:d.total??null};source=d.sourceText||JSON.stringify(d,null,2);}if(!fields.vendor&&!fields.number&&!invoiceDocument)throw Error('No supplier or reference could be read. Try a clearer document.');const hash=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());docs.push({id:crypto.randomUUID(),name:file.name,file:file.name,source,fields,invoiceDocument,requiresPo:documentType==='invoice',documentType,status:'queued',fingerprint:[...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('')});$('#search').value=fields.number||fields.vendor;window.dispatchEvent(new Event('rekono-document-added'));recheck();log(`Imported ${file.name}; entire queue checked for duplicates.`);render();}catch(err){toast(file.name+': '+err.message);}}}finally{busy=false;persist();render();}}
function render(){
 duplicatesUI.render();
 const queued=docs.filter(d=>d.status==='queued').length,review=docs.filter(d=>d.status==='review').length,approved=docs.filter(d=>d.status==='approved');
 $('#queue-count').textContent=queued;$('#total-count').textContent=docs.length;
 $('#stats').innerHTML=[['Invoices received',docs.length,'Documents in this workspace','▤'],['Total invoice value',money(docs.filter(d=>d.status!=='rejected').reduce((a,d)=>a+(Number(d.fields.total)||0),0)),'Includes unreviewed documents','↗'],['Needs your attention',review,'Exceptions to resolve','◷'],['Approved for export',approved.length,money(approved.reduce((a,d)=>a+effectiveFields(d).total,0))+' approved','✓']].map(([a,b,c,i])=>`<div class="stat"><div class="stat-label">${a}<span>${i}</span></div><div class="stat-value">${b}</div><small>${c}</small></div>`).join('');
 const search=$('#search').value.toLowerCase();const shown=docs.filter(d=>(filter==='all'||d.status===filter)&&`${d.fields.vendor} ${d.fields.number} ${d.name}`.toLowerCase().includes(search));
 $('#rows').innerHTML=shown.map(d=>`<tr><td><div class="vendor"><span class="file-icon">▤</span><div><strong>${esc(d.fields.vendor||'Unknown vendor')}</strong><small>${esc(d.name)}</small></div></div></td><td>${esc(d.fields.number||'—')}</td><td>${money(effectiveFields(d).total||0)}${d.workflow?.state==='resolved'?`<small class="workflow-status">Original ${money(d.fields.total)}</small>`:''}</td><td><span class="status ${d.status}">${labels[d.status]}</span><small class="workflow-status">${d.workflow?.state==='resolved'?'Correction resolved · payment not approved':d.workflow?.state==='on_hold'?'PO discrepancy · payment on hold':d.workflow?.state==='revision_ready'?'Correction received · verify resolution':d.workflow?.state==='matched'?'PO matched':d.requiresPo?'Awaiting PO comparison':'PO not linked'}</small></td><td><button class="row-action" data-open="${esc(d.id)}">${d.status==='queued'?'View':'Review'} ↗</button>${(!['queued','rejected','approved'].includes(d.status)||(d.status==='approved'&&d.workflow?.case))?`<button class="row-action" data-match="${esc(d.id)}">${d.status==='approved'?'View case':d.workflow?.case?'Continue case':'Match purchase order'} →</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No invoices match this view.</td></tr>';
 $('#shown').textContent=`Showing ${shown.length} of ${docs.length} invoices`;
 $('#process').disabled=!queued||busy;$('#process').textContent=busy?'Processing invoices…':queued?'✦ Process all invoices':'✓ All invoices processed';$('#export').disabled=!approved.length;
 $('#activity').innerHTML=events.map(e=>`<div class="activity-item">${esc(e.message)}<small>${esc(new Date(e.time).toLocaleString())}</small></div>`).join('')||'<p class="empty">Process your first invoice to start the activity log.</p>';
}
function download(text,name,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function current(){return docs.find(d=>d.id===selected);}
function showDetail(id){selected=id;const d=current();$('#match-from-detail').disabled=['queued','rejected'].includes(d.status)||(d.status==='approved'&&!d.workflow?.case);$('#match-from-detail').textContent=d.status==='approved'&&d.workflow?.case?'View resolution case →':d.workflow?.case?'Continue resolution case →':'Match purchase order →';$('#detail-title').textContent=d.fields.vendor||'Invoice details';$('#source').textContent=d.source;$('#fields').innerHTML=[['vendor','Vendor','text'],['number','Invoice number','text'],['date','Invoice date','date'],['due','Due date','date'],['subtotal','Subtotal ($)','number'],['tax','Tax ($)','number'],['total','Total ($)','number']].map(([k,label,type])=>`<label>${label}<input name="${k}" type="${type}" ${type==='number'?'min="0" step="0.01"':''} value="${esc(d.fields[k])}" ${['queued','rejected','approved'].includes(d.status)?'disabled':''}></label>`).join('');$('#verify-label').hidden=!d.lowConfidence;$('#verified').checked=d.verified;$('#verified').disabled=['queued','rejected','approved'].includes(d.status);const issues=issuesFor(d,docs);$('#corrected-summary').hidden=d.workflow?.state!=='resolved';$('#corrected-summary').textContent=d.workflow?.state==='resolved'?`Verified replacement ${effectiveFields(d).number}: ${money(effectiveFields(d).total)} will be exported. The original invoice fields below remain preserved.`:'';$('#checks').innerHTML=d.status==='queued'?'<div class="check">Process this invoice from the inbox to start validation.</div>':d.status==='rejected'?'<div class="check">Rejected. This invoice is excluded from exports.</div>':issues.length?issues.map(i=>`<div class="check">${esc(i)}</div>`).join(''):`<div class="check ok">✓ ${d.status==='approved'?'Approved and ready to export.':'Required fields, total and duplicate checks passed.'}</div>`;$('#save').disabled=!['review','ready'].includes(d.status);$('#approve').disabled=!['review','ready'].includes(d.status)||issues.length>0;$('#reject').disabled=['queued','rejected','approved'].includes(d.status);if(!$('#detail').open)$('#detail').showModal();}
$('#close-detail').onclick=()=>$('#detail').close();$('#download-source').onclick=()=>download(current().source,current().file.endsWith('.json')?current().file:'invoice-source.txt');
$('#match-from-detail').onclick=()=>continueInvoice(selected);
$('#rows').onclick=e=>{const match=e.target.closest('[data-match]');if(match){continueInvoice(match.dataset.match);return;}const b=e.target.closest('[data-open]');if(b)showDetail(b.dataset.open);};
$('#edit-form').onsubmit=e=>{e.preventDefault();const d=current();if(!['review','ready'].includes(d.status))return;const before=sourceStamp(d);const data=new FormData(e.target);for(const k of ['vendor','number','date','due'])d.fields[k]=String(data.get(k)).trim();for(const k of ['subtotal','tax','total'])d.fields[k]=data.get(k)===''?null:Number(data.get(k));d.verified=$('#verified').checked;if(sourceStamp(d)!==before&&d.workflow){d.workflowHistory=[...(d.workflowHistory||[]),d.workflow];delete d.workflow;d.requiresPo=true;}recheck();log(`Updated and rechecked ${d.fields.number||'invoice'}.`);render();showDetail(selected);toast('Changes saved. Validation updated.');};
$('#approve').onclick=()=>{try{const d=current();if(!['ready','review'].includes(d.status))return;const data=new FormData($('#edit-form'));if(['vendor','number','date','due','subtotal','tax','total'].some(k=>String(data.get(k))!==String(d.fields[k]??''))||$('#verified').checked!==d.verified){toast('Save & recheck your changes before approving.');return;}docs=docs.map(x=>x.id===selected?approve(x,docs):x);log(`Approved ${effectiveFields(d).number} for ${money(effectiveFields(d).total)} for export only.`);render();showDetail(selected);toast('Invoice approved. Ready for CSV export.');}catch(e){toast(e.message);}};
$('#reject').onclick=()=>{const d=current();if(!['review','ready'].includes(d.status))return;d.status='rejected';recheck();log(`Rejected ${d.fields.number}.`);render();showDetail(selected);toast('Invoice rejected and excluded from exports.');};
$('#process').onclick=async()=>{busy=true;render();await new Promise(r=>setTimeout(r,650));const count=docs.filter(d=>d.status==='queued').length;docs=processDocs(docs);busy=false;log(`Processed ${count} invoice${count===1?'':'s'}: parsed fields and ran validation checks.`);render();toast('Processing complete. Open an invoice to review its checks.');};
$('#export').onclick=()=>{const approved=docs.filter(d=>d.status==='approved');if(!approved.length)return;download(csv(docs),'approved-invoices.csv','text/csv;charset=utf-8');log(`Exported ${approved.length} approved invoices to CSV.`);render();toast('Approved invoices exported.');};
$('.tabs').onclick=e=>{const b=e.target.closest('[data-filter]');if(!b)return;filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render();};$('#search').oninput=render;
const titles={cases:['From exception to resolution.','Preserve the evidence. Verify the correction. Keep payment under human control.','Resolution case'],duplicates:['Catch duplicates. Keep the evidence.','Review suspected matches across your entire invoice queue.','Duplicate review'],matching:['Every difference, explained.','Compare the invoice to what you ordered. Keep control of the next step.','Match invoice & PO'],invoices:['Your invoices. In order.','From incoming document to approved invoice, all in one place.','Invoice inbox'],samples:['Meet your sample documents.','A small library to explore every step of the workflow.','Sample documents'],activity:['Every action, accounted for.','Follow the decisions made in this demo workspace.','Activity log']};
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{const p=b.dataset.page;for(const n of Object.keys(titles))$('#'+n+'-page').hidden=n!==p;document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x===b));$('#heading').textContent=titles[p][0];$('#subtitle').textContent=titles[p][1];$('#breadcrumb').textContent=titles[p][2];$('#upload').hidden=p==='matching';});
$('#sample-grid').innerHTML=samples.map(s=>`<article class="sample-card"><div class="sheet"></div><span class="demo-badge">${esc(s.scenario)}</span><h3>${esc(s.vendor)}</h3><p>${esc(s.number)} · ${money(s.total)}</p><button class="button secondary" data-sample="${s.id}">Open sample ↗</button><a href="samples/${s.file}" download>Download original .txt ↓</a></article>`).join('');$('#sample-grid').onclick=e=>{const b=e.target.closest('[data-sample]');if(b)showDetail(b.dataset.sample);};
$('#reset').onclick=()=>{if(busy)return;if(!confirm('Reset all demo decisions, imports and activity?'))return;window.dispatchEvent(new Event('invoicing-reset'));docs=newDocs();events=[];filter='all';$('#search').value='';document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x.dataset.filter==='all'));persist();render();toast('Demo reset. Five sample invoices are ready.');};
$('#upload').onclick=()=>$('#file-input').click();$('#file-input').onchange=async e=>{await importQueueFiles([...e.target.files]);e.target.value='';};
async function continueInvoice(id){const d=docs.find(x=>x.id===id);if(!d||['queued','rejected'].includes(d.status)||(d.status==='approved'&&!d.workflow?.case))return;$('#detail').close();try{if(d.workflow?.case){openInboxCase(d);return;}if(!d.invoiceDocument){const data={...parseExtractedText(d.source,'invoice'),type:'invoice',vendor:d.fields.vendor,number:d.fields.number,tax:d.fields.tax,total:d.fields.total,currency:'USD'};const verified=await reviewExisting(data,d.source);if(!verified)return;d.invoiceDocument=verified;d.fields={...d.fields,vendor:verified.vendor,number:verified.number,tax:verified.tax,total:verified.total,subtotal:verified.subtotal??verified.lines.reduce((n,l)=>n+l.quantity*l.unitPrice,0)};}d.requiresPo=true;recheck();persist();render();openInboxMatch(d);}catch(e){toast(e.message);}}
$('#load-workflow').onclick=async()=>{if(busy)return;const existing=docs.find(d=>d.id==='connected-example');if(existing){$('#search').value=existing.fields.number;render();window.dispatchEvent(new Event('rekono-document-added'));document.querySelector('[data-page=invoices]').click();toast('The $60 example is already in your inbox. Process or continue it below.');return;}try{const [invoice,po]=await Promise.all(['samples/matching-invoice.json','samples/matching-po.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error('Could not load example documents.');return r.json();}));docs.push({id:'connected-example',name:'$60 discrepancy · complete workflow',file:'matching-invoice.json',source:JSON.stringify(invoice,null,2),invoiceDocument:invoice,purchaseOrder:po,requiresPo:true,documentType:'invoice',fields:{vendor:invoice.vendor,number:invoice.number,due:invoice.due||'',subtotal:invoice.lines.reduce((n,l)=>n+l.quantity*l.unitPrice,0),tax:invoice.tax,total:invoice.total},status:'queued',verified:true});window.dispatchEvent(new Event('rekono-document-added'));log('Added the $60 invoice and its purchase order to the inbox.');render();toast('Example added. Process invoices, then choose Match purchase order.');}catch(e){toast(e.message);}};

recheck();persist();render();

window.dispatchEvent(new Event('inbox-ready'));
document.querySelector('[data-page=invoices]').click();
